package com.servicerca.model;
import jakarta.persistence.*;import lombok.*;import java.time.Instant;import java.util.UUID;
@Entity @Table(name="rating") @Getter @Setter @Builder @NoArgsConstructor @AllArgsConstructor public class Rating { @Id @GeneratedValue(strategy=GenerationType.UUID) private UUID id; @ManyToOne(optional=false) @JoinColumn(name="request_id") private ServiceRequest request; @ManyToOne(optional=false) @JoinColumn(name="author_id") private User author; @ManyToOne(optional=false) @JoinColumn(name="target_id") private User target; @Column(nullable=false) private short score; @Column(length=600) private String comment; @Column(name="created_at",nullable=false) private Instant createdAt; @PrePersist void prePersist(){if(createdAt==null)createdAt=Instant.now();} }
